text:
{
  "title": "اتفاقية الخدمات ومعالجة البيانات",
  "planted": [
    {
      "slot": "p1",
      "text": "يحق للمستفيد استخدام كافة البيانات والمعلومات المجمعة والمقدمة במסגרة هذه الاتفاقية لأي غراض تشغيلية أو تجارية تراه الشركة مناسباً لتطوير أعمالها المستقبلية، بما في ذلك الأغراض التي لم تكن محددة بانتهاء نطاق الخدمات الأصلي."
    },
    {
      "slot": "p2",
      "text": "يُفوض المورد بموجب هذه الاتفاقية بتفويض أي أطراف ثالثة أو مقاولين من الباطن لتقديم الخدمات ومعالجة البيانات دون الحاجة لإشعار مسبق، وتعفى جهة الإدارة من أي التزام بإجراء عمليات تدقيق أو مراجعة ميدانية على أنظمة المورد."
    },
    {
      "slot": "p3",
      "text": "تستمر الجهة مقدمة الخدمة في الاحتفاظ بجميع السجلات والبيانات لفترات غير محدودة زمنياً تضمن استدامة السجلات التاريخية للمشروع، مع احتفاظها بالحق في حفظها دون التزام بإتلافها نهائياً."
    },
    {
      "slot": "p4",
      "text": "يلتزم المورد بإخطار الطرف الأول خطياً خلال مدة لا تتجاوز أربع وعشرين ساعة من تاريخ اكتشاف أي اختراق أو وصول غير مصرح به للبيانات، لتقوم الشركة لاحقاً باتخاذ التدابير اللازمة وإبلاغ الجهات المعنية بالدولة خلال اثنين وسبعين ساعة وفق الإجراءات النظامية المعتمدة."
    }
  ],
  "neutral": [
    "تُحتسب أتعاب الخدمات محل هذه الاتفاقية وفقاً للجداول المالية المرفقة، وتلتزم الشركة بسداد المبالغ المستحقة خلال ثلاثين يوماً من تاريخ استلام الفواتير الضريبية المعتمدة.",
    "تبدأ هذه الاتفاقية اعتباراً من تاريخ توقيع الطرفين وتستمر لمدة سنة ميلادية واحدة، وتجدد تلقائياً لفترات مماثلة ما لم يقم أحد الطرفين بإشعار الطرف الآخر برغبته في عدم التجديد قبل موعد الانتهاء بشهرين على الأقل.",
    "تظل جميع حقوق الملكية الفكرية والعلامات التجارية والبرمجيات الخاصة بكل طرف ملكاً خالصاً له، ولا تمنح هذه الاتفاقية أي حق في نقل ملكيتها أو استخدامها إلا بالقدر اللازم لتنفيذ الخدمات.",
    "تخضع هذه الاتفاقية وتفسر وفقاً لأنظمة وقوانين المملكة العربية السعودية، وفي حال نشوء أي نزاع -لا قدر الله- يتم تسويته وديّاً، فإن لم يُحل فيتم عرضه أمام الجهات القضائية المختصة.",
    "تُوجه كافة الإشعارات والمراسلات الرسمية المتعلقة بتنفيذ هذه الاتفاقية كتابةً عبر البريد الإلكتروني أو العناوين الرسمية الموضحة في ديباجة هذا العقد."
  ]
}
